T[30] = { { "Thrash", "Now and then, two extra attacks: heavy hits on the tank." }, { "VanCleef's Allies", "At half health, he calls two Defias Blackguards." } }
T[31] = { { "Acid Splash", "Nature damage every 5 seconds for 30 seconds to everyone near him." }, { "Cookie's Cooking", "Below half health, he heals himself (2-second cast). Interrupt him." }, { "Runs for Help", "At 15% health, he runs off to get help. Finish him before he gets away." } }
T[32] = { { "Soul Drain", "Roots a player for 10 seconds and drains their health to heal himself. Interrupt the 2-second cast or dispel it." } }
T[33] = { { "Crooked Blow", "The Fel Steed stuns everyone near it for 3 seconds, and they take more physical damage. The Shadow Charger has no special abilities." } }
T[34] = { { "Butcher Drain", "Drains 350 mana from his target in melee: a tank with mana will feel it." } }
T[35] = { { "Veil of Shadow", "Curses a player: healing they receive is reduced by 75% for 15 seconds. Remove it, especially on the tank." } }
T[36] = { { "Holy Light", "Heals himself or an ally (2.5-second cast). Interrupt him." }, { "Divine Shield", "Makes him immune to all damage and spells for 10 seconds." }, { "Hammer of Justice", "Stuns a player for 4 seconds." } }
T[37] = { { "Call for Help", "When you engage him, he calls creatures within 30 yards. Clear around him first." }, { "Howling Rage", "At 60%, 40% and 20% health, his hits get stronger." } }
T[38] = { { "Cleave", "Hits his target and the player nearest to it." }, { "Hamstring", "Slows his target's movement for 10 seconds." } }
T[39] = { note = "They arrive as a group of four after Fenrus the Devourer dies: Arugal appears briefly and summons them.", { "Dark Offering", "Heals another Voidwalker. Kill them one at a time." } }
T[40] = { { "Toxic Saliva", "Nature damage every 6 seconds and drained mana, for 2 minutes. Cure the poison." } }
T[41] = { { "Worg Reinforcements", "The longer the fight lasts, the more worgs he has with him: a Bleak Worg after 30 to 45 seconds, then a Slavering Worg, then a Lupine Horror." } }
T[42] = { { "Void Bolt", "A 3-second Shadow bolt on the tank, over and over. Interrupt him." }, { "Arugal's Curse", "Turns a player other than the tank into a Shadowfang Glutton that fights for him for 10 seconds. Remove the curse." }, { "Shadow Port", "He teleports between his ledge, the upper ledge and the stairs." }, { "Thunderclap", "When the tank reaches him: Nature damage and a 5-second stun around him." } }
T[43] = { { "Trample", "Hits everyone standing near him." } }
T[44] = { { "Forked Lightning", "Nature damage in a cone in front of her (2-second cast). Stay out of the cone." }, { "Frost Nova", "Freezes everyone near her in place for up to 8 seconds." }, { "Slow", "Slows a player's movement and attacks for 10 seconds." } }
T[45] = { { "Net", "Roots a player in place for 10 seconds." } }
T[46] = { note = "Click the Fathom Stone in the water: he rises from it.", { "Frostbolt", "He keeps his distance to cast it: Frost damage and a slow." }, { "Frost Nova", "Roots everyone near him for up to 8 seconds." } }
T[47] = { { "Sleep", "Puts everyone near him to sleep for up to 10 seconds. Damage wakes a sleeper." }, { "Mind Blast", "Shadow damage on a player (1.5-second cast)." } }
T[48] = { note = "He waits in an underwater cave beneath Twilight Lord Kelris's temple, and many groups miss him. Swim under the temple to reach him." }
T[49] = { note = "Once Twilight Lord Kelris is dead, light the four Aku'Mai fires in his room, one after the other. Each one brings a wave of creatures. When they are all dead, Aku'Mai's door opens.", { "Poison Cloud", "Nature damage every 5 seconds for 45 seconds to everyone nearby." }, { "Frenzied Rage", "Below 30% health: bursts of attacks 75% faster, over and over." } }
T[50] = { { "Lightning Shield", "Lightning strikes anyone who touches him. A priest or shaman can remove it." }, { "Lightning Bolt", "He keeps his distance to cast it. Interrupt him." } }
T[51] = { { "Shield Bash", "Hits the tank and stuns them for 2 seconds." }, { "Runs for Help", "At 15% health, he runs off to get help. Finish him before he gets away." } }
T[52] = { { "Runs for Help", "At 15% health, he runs off to get help. Finish him before he gets away." } }
T[53] = { { "Thrash", "Now and then, two extra attacks: heavy hits on the tank." }, { "Enrage", "At 30% health, he attacks 30% faster until the end of the fight." } }
T[54] = { { "Chain Lightning", "A bolt that bounces from player to player (2-second cast). Interrupt him." }, { "Bloodlust", "Speeds up his attacks or an ally's by 30% for 30 seconds. A priest or shaman can remove it." } }
T[55] = { { "Smoke Bomb", "Stuns everyone near him for 4 seconds." }, { "Battle Shout", "More attack power for him and his allies for 2 minutes." }, { "Runs for Help", "At 15% health, he runs off to get help. Finish him before he gets away." } }
T[56] = { { "Strike", "Strikes the target for weapon damage plus 5. Keep the tank healed." } }
T[57] = { { "Lots of health", "Nothing special seen during the fight: he hits and has a lot of health. He roams the starting marsh among elite crocolisks, so clear them first or pull him away from them." } }
T[58] = { note = "Kill the raptor matriarch in the tall grass. A wave of raptors arrives when she dies, and Shadetooth rushes in once they are dead.", { "Raptors in the grass", "Small raptors burst out of the grass as you walk through it and make you bleed." }, { "The wave before him", "Kill all the raptors in the wave before he arrives. One group died on their first attempt with Shadetooth and several raptors on them at once." }, { "Fear", "The tank is feared several times during this fight. A shaman's Tremor Totem helps." } }
T[59] = { note = "He stands still at the end of the spiders' path. Click the small sign next to him to wake him.", { "Threat reset", "He resets his threat and switches targets during the fight. Damage dealers, slow down when the tank loses him. Tank, take him back right away." } }
T[60] = { { "The Dragonmaw camp", "He stands in a Dragonmaw camp. Their groups are easily pulled one at a time: take them one at a time first. The fight itself is short, nothing special seen so far." } }
T[61] = { note = "He stands next to a ritual circle in the sewers, surrounded by Kirin Tor necromancers.", { "Unholy Frenzy", "His attacks are 75% faster for 20 seconds. It is magic: a shaman's Purge or a priest's Dispel Magic removes it." }, { "Thrash", "Occasionally he hits twice more in a single strike, and Strike adds damage to his next hit: the tank takes big hits." }, { "Raise Dead", "Skeletons keep rising around the circle throughout the fight. They are weak: kill them as they come." }, { "Disarm", "He disarms the tank for about 6 seconds." } }
T[62] = { { "Focused Blast", "After a 3-second cast, a beam fires in front of him for 6 seconds and hits four times per second. Get out of its path as soon as the cast starts." }, { "Arcane Bolt", "His attack on the tank between two beams, 1.5-second cast." } }
T[63] = { { "Manamorph", "Turns a player into an animal for 8 seconds. It is magic: dispel it." }, { "Silence", "Silences for 10 seconds. Healers, keep your distance." }, { "Arcane Manalings", "He constantly summons small Arcane Manalings. Kill them with area damage." } }
T[64] = { { "Malfunction", "2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged, stay beyond 25 yards; melee, move out during the cast." }, { "Angry Tomes", "Angry Tomes rush you along the way. Kill them before engaging the boss." } }
T[65] = { { "Debilitate", "2-second cast: arcane energy drains up to 200 mana from everyone within 45 yards of him." }, { "Vitality Drain", "A magic effect on the tank: about 65 Arcane damage every 2 seconds for 10 seconds. Dispel it." }, { "His room", "Creatures still alive in his room join the fight when you engage him. Clear the room first." } }
T[66] = { note = "He waits behind a magical barrier in the center of the city, guarded by Suffused Treants. Kill the treants, then talk to magus Fansy Goodbringer, just south of the barrier: he brings it down.", { "Fel Brambles", "Vines shoot toward a player and hit everyone within 5 yards of them, then leave toxic fumes on the ground. Move out of the fumes." }, { "Trample", "He tramples players next to him for about 100 physical damage." }, { "Entangle", "Roots up to two players near him for a few seconds and damages them over time. It is magic: dispel it." } }
T[67] = { note = "She is not there at the start. In the sewers, after Atrexis, clear the northeast room, the one with market stalls and a small pink summoning circle (not Atrexis's large circle). A player carrying the Tome of Dalaran then clicks the circle, and Lyn comes out of the large round barred gate. To get the tome, pick up the Dark Tome lying on the table in Archmage Arugal's room in Shadowfang Keep once Arugal is dead, then use it at the Leyline Focus, a blue crystal in a back room of Ambermill, in Silverpine Forest.", { "Shadow Bolt Volley", "Shadow bolts on everyone within 30 yards of her." }, { "Curse of Thorns", "1.5-second cast: a 3-minute curse that occasionally damages the player when they attack. Remove it." }, { "Skeletons", "Skeletons rise and fight alongside her. Kill them." } }
T[68] = { note = "Archmage Modera opens a portal for the group to the purple chamber: it leads to him.", { "Rebounding Mana", "An orb rushes toward a random player then returns to him. Everyone it passes through takes Arcane damage and is silenced for 6 seconds: do not stand between him and that player." }, { "Mass Polymorph", "When he runs out of mana, he turns the whole group into animals for 8 seconds, then channels Evocation for 6 seconds to refill it." }, { "Slow", "Slows everyone around him for 3 seconds: attacks and casts 30% slower, movement 70% slower." }, { "Stay in the room", "If anyone leaves the room during the fight, he returns to full health." } }
T[69] = { { "Net", "Roots everyone near him for 10 seconds." }, { "Slow", "Slows a player's attacks and movement for 10 seconds, and can stun them." }, { "Summon Mechanical Roach", "Calls mechanical roaches. His Update kills them and heals him." } }
T[70] = { note = "Talk to Blastmaster Emi Shortfuse and protect her while she blows up the two cave entrances. Troggs come in waves, then Grubbis arrives with Chomper." }
T[71] = { { "Megavolt", "Nature damage in a cone in front of him (2-second cast). Only the tank stands in front." }, { "Chain Lightning", "A bolt that bounces between nearby players (2.5-second cast). Interrupt him." } }
T[72] = { { "Crowd Pummel", "Hits everyone near him and interrupts their spells. Casters and healers, keep your distance." }, { "Arcing Smash", "Hits everyone in a cone in front of him." }, { "Trample", "Hits everyone standing near him." } }
T[73] = { { "Summon Fiery Servant", "Calls two fiery servants at the start of the fight." }, { "Fireball", "He keeps his distance to cast it. Interrupt him." }, { "Fire Shield II", "Fire damage to everyone near him for one minute. A priest or shaman can remove it." } }
T[74] = { { "Walking Bombs", "He lights the gnome heads around the room one by one, and each one drops walking bombs that explode when they reach a player. The button next to a head turns it off. Below half health, he lights them faster." }, { "Knock Away", "Knocks the tank back. Below half health, it hits everyone around him." } }
T[75] = { { "Summon Boar Spirit", "Calls a Boar Spirit to his side every 30 to 45 seconds (1.5-second cast). Kill each one before the next arrives." }, { "Chain Heal", "Below 75% health, he heals himself, and the heal bounces to two nearby allies (2.5-second cast). Interrupt it." } }
T[76] = { { "Dominate Mind", "Takes control of a player other than its target for 15 seconds (2-second cast). Interrupt it, or dispel the effect from the player." }, { "Shadow Bolt", "He keeps his distance to cast it. Interrupt it." } }
T[77] = { { "Calls for help", "When you engage him, he calls creatures within 15 yards, including the two Razorfen Warders at his side. Keep one of the two under control during the fight." }, { "Thunderclap", "Every 8 to 14 seconds: Nature damage to everyone near him, and their attacks and movement are slowed for 10 seconds." } }
T[78] = { { "Whirling Barrage", "Hits everyone standing near him." }, { "Thorns Aura", "Anyone who hits him, or a nearby ally (Overlord Ramtusk included), takes Nature damage." } }
T[79] = { note = "A ward seals his cave. Kill the two Deathskull Wardens stationed in front: it falls when both are dead.", { "Left for Dead", "Every 21 to 35 seconds, he strikes a player other than his target, who falls as if dead and can no longer attack or cast. Moving ends it." }, { "Rampage", "Every 25 to 31 seconds: hits everyone near him and stuns them for 2.5 seconds." }, { "Enrage", "At 60% health, then at 40%, he attacks 60% faster and hits harder for 2 minutes." } }
T[80] = { note = "A rare bat: it is not there every run. When it is, it waits in a small recess in the wall of the bat cave, near Charlga Razorflank." }
T[81] = { { "Chain Lightning", "She keeps her distance and casts it over and over: a lightning bolt that bounces to up to 3 players (2.5-second cast). Interrupt it." }, { "Purity", "Every 9 to 15 seconds, she is immune to all attacks and spells for 2 seconds." }, { "Renew", "Heals a wounded ally, or herself, over 15 seconds. A priest or shaman can remove it." } }
T[82] = { { "Summon Earth Rumbler", "A Stone Rumbler accompanies him and fights at his side." }, { "Lightning Bolt", "He keeps his distance to cast it. Interrupt it." }, { "Flees for help", "At 15% health, he runs off to get help. Finish him before he gets away." } }
T[83] = { { "Summon Earth Rumbler", "A Stone Rumbler accompanies him and fights at his side." }, { "Lightning Bolt", "He keeps his distance to cast it. Interrupt it." } }
