T[88] = { { "Flame Spike", "A column of flames where a player stands (3-second cast): Fire damage, then again every 3 seconds for 9 seconds. Move out of it." }, { "Fire Nova", "Fire damage to everyone within 10 yards of him." }, { "Flame Shock", "Fire damage to a player, then again every 3 seconds for 12 seconds. A Dispel Magic removes it." }, { "Shadow Bolt", "He keeps his distance to cast it. Interrupt it." } }
T[89] = { { "Scarlet Hounds", "Three dogs accompany him and attack with him, and he also gives them Bloodlust. Kill them first." }, { "Bloodlust", "Speeds up his attacks or an ally's by 30% for 30 seconds. A priest or shaman can remove it." }, { "Battle Shout", "More attack power for him and his dogs for 3 minutes." } }
