T[95] = { { "Dominate Mind", "Controls a player for 10 seconds. Dispel the effect and don't let the controlled player hurt the group." }, { "Shadow Word: Pain", "Shadow damage every 3 seconds for 18 seconds. Dispel it." }, { "Heal", "Heals himself or an ally. Interrupt the cast." }, { "Shadow Bolt", "Bolt of Shadow damage on a target, 3 second cast. Interrupt it." } }
T[96] = { { "Amnennar's Wrath", "Knocks a target back. Get back into position." }, { "Frostbolt", "Frost bolt that slows his target, cast again and again. Interrupt it." }, { "Frost Nova", "Frost damage and a root on everyone near him. Dispel the root." } }
T[97] = { { "Withered Touch", "Disease dealing Shadow damage and draining mana every 10 seconds for 3 minutes, giving the mana to him. Cure it, mostly on casters." }, { "Putrid Stench", "Lowers Strength and Agility of nearby players by 50 for 10 seconds and prevents them from casting spells. Casters, stay away from him." } }
T[98] = { note = "He lies on the floor in the small room next to the altar, as if dead, and gets up when attacked.", { "Fear", "Makes a player flee in terror for up to 8 seconds (1.5-second cast). Interrupt it." }, { "Sleep", "Puts everyone near him to sleep for up to 10 seconds. Damage wakes a sleeper." }, { "Curse of Blood", "A player takes more physical damage for 10 minutes (2-second cast). A mage or druid can remove it." }, { "Heal", "At 30% health, he heals himself (3-second cast). Interrupt it." } }
T[99] = { { "Calls for help", "When you engage him, he calls all Scarlet defenders within 80 yards. Clear the cathedral before engaging him." }, { "Hammer of Justice", "Stuns a player for 5 seconds." }, { "Divine Shield", "At half health, he becomes immune to all damage and spells for 12 seconds." }, { "Retribution Aura", "Holy damage to anyone who hits him in melee." } }
T[100] = { note = "When Mograine falls, he is only playing dead: she comes out of the room behind the altar and attacks.", { "Scarlet Resurrection", "At half health, she puts the whole room to sleep for up to 10 seconds, runs to Mograine and resurrects him. He restores all her health with Lay on Hands, and the two fight you together." }, { "Holy Smite", "Holy damage to her target (2.5-second cast). Interrupt her." }, { "Heal", "Heals the most wounded of her allies, Mograine included (3-second cast). Interrupt her." }, { "Power Word: Shield", "Protects her from damage for up to 30 seconds. A priest or shaman can remove it." } }
T[101] = { { "Rushing Charge", "Speeds him up for 3 seconds and adds damage to his first attack. Heal whoever gets hit." } }
T[102] = { { "Strike", "A stronger melee hit on its target. Heal the tank." } }
T[103] = { { "Shield Slam", "Bashes his target and stuns it for 2 seconds. Heal through the stun." } }
