T[105] = { { "Arcing Smash", "A sweeping hit on everyone in front of her. Stay out of her front arc." }, { "Knock Away", "Deals extra damage to its target and knocks it back. Heal the tank." }, { "War Stomp", "Knocks back and stuns everyone close to it for 5 seconds. Heal through the stun." } }
T[106] = { { "Sand Storms", "Summons a Sand Storm that fights for him for 30 seconds. Kill it or move away from it." }, { "Sand Storms", "Summons a Sand Storm that fights for him for 30 seconds. Kill it or move away from it." } }
