T[211] = { { "Ground Smash", "Physical damage to nearby players and a 3-second stun. Keep your healer alive." }, { "Holy Light", "Heals an ally. Interrupt the cast." }, { "Head Crack", "Lowers the target's Stamina by 1 for 20 seconds. Minor, just keep the tank healed." }, { "Lay on Hands", "Fully heals an ally. Kill the weaker target first." } }
T[212] = { { "Bone Smelt", "A big Fire hit on one target that halves their armor for 20 seconds. Heal that target." } }
T[213] = { { "Knock Away", "Hits his target and knocks it back. The tank should keep him from turning on the group." } }
T[214] = { { "Burning Winds", "Stuns a player, then burns them for 1600 Fire damage over 8 seconds. Dispel it and heal the target." }, { "Fire Nova", "A burst of Fire damage on everyone nearby. Heal the group." } }
T[215] = { { "Sleep", "Puts one player to sleep for up to 20 seconds. Dispel it." }, { "Psychic Scream", "Fears up to 5 nearby players for 6 seconds. Use a fear ward or stay away from the group's edge." }, { "Crusader Strike", "Damages the target and raises the Holy damage it takes by 30 per application, up to 5 times for 30 seconds. Keep the tank healed." }, { "Holy Strike", "Empowers the weapon for 3 extra Holy damage on its next attack. Minor, keep the tank healed." }, { "Crusader's Hammer", "Stuns nearby players for 4 seconds. Heal the group." }, { "Mind Blast", "Big Shadow damage on one target. Keep everyone topped off." }, { "Shadow Shock", "Shadow damage to nearby players. Heal the group." }, { "Domination", "Mind-controls a player for 15 seconds. Crowd control the controlled player." } }
T[216] = { { "Crowd Pummel", "Hits everyone near him and interrupts spellcasting 75% of the time for 5 seconds. Casters, stay out of melee range." }, { "Mighty Blow", "Deals extra damage and knocks the target back. Tank, keep your back to a wall." }, { "Furious Anger", "Enrages him. Keep the tank healed." }, { "Draining Blow", "Drains 250 health from a target and transfers it to him. Heal through it." } }
T[217] = { { "Vicious Rend", "Deals Physical damage every 3 seconds for 15 seconds. Heal the tank." } }
T[218] = { { "Banshee Curse", "Reduces the chance to hit of nearby players by 10% for 12 seconds. Remove the curse." } }
T[219] = { { "Encasing Webs", "Immobilizes a player and increases the time between their attacks by 100% for 6 seconds. Heal the webbed player." }, { "Pierce Armor", "Cuts the target's armor by 50% for 20 seconds. Heal the tank accordingly." }, { "Crypt Scarabs", "Summons 8 scarabs for 10 seconds. Kill them fast or use area damage." }, { "Raise Undead Scarab", "Raises a scarab that joins the fight. Kill it fast." } }
T[220] = { { "Ice Tomb", "Entombs a target in ice, stunning it for 10 seconds. Interrupt the 1.5-second cast or heal through it." }, { "Drain Life", "Drains life from his target for 5 seconds and heals him. Interrupt it or heal through it." }, { "Drain Mana", "Channels for 5 seconds to drain up to 150 mana and give it to him. Interrupt it." }, { "Frostbolt", "Frost damage and slows the target's movement for 4 seconds. Interrupt it when you can." } }
T[221] = { { "Trample", "Deals physical damage to nearby players. Stay out of melee range if you can." }, { "Knockout", "Deals extra damage to a target, knocking it back and stunning it for 6 seconds. Heal the stunned player." } }
T[222] = { { "Mortal Strike", "Heavy hit on the tank that cuts healing received by 50% for 5 seconds. Heal in advance." }, { "Cleave", "Hits a target and its nearest allies, up to 3 targets, with weapon damage. Don't stand next to the tank." }, { "Shadow Bolt", "A Shadow bolt on his target. Interrupt it when you can." }, { "Shadow Bolt", "A Shadow bolt on his target. Interrupt it when you can." }, { "Shadow Bolt", "A Shadow bolt on his target. Interrupt it when you can." }, { "Unholy Aura", "Shadow damage to everyone in range, about every 2 seconds. Tank him against one wall and keep ranged and healers on the opposite wall. Shadow Protection helps." } }
T[223] = { { "Fire Nova", "Fire damage to nearby players. Heal the group." }, { "Flame Buffet", "Fire damage on one target that increases the Fire damage it takes by 30 for 45 seconds. Keep the tank healed." } }
T[224] = { { "War Stomp", "Damages nearby players, knocks them back and stuns them for 5 seconds. Heal through it." } }
T[225] = { { "Backhand", "Stuns the target for 2 seconds. Keep the tank healed." }, { "Strike", "Strikes the target for increased melee damage. Keep the tank healed." }, { "Head Crack", "Lowers the target's Stamina by 1 for 20 seconds. Minor, just keep the tank healed." } }
T[226] = { { "Knock Away", "Damages an enemy and knocks it back. Tank, keep your back to a wall." }, { "Freeze", "An icy blast in front of him: stuns, deals Frost damage, then more every 3 seconds for 10 seconds. Stay out of the front." }, { "Corrosive Acid Breath", "Acid breath in front of him: lowers armor and deals Nature damage every 5 seconds. Keep the tank healed, others stay behind." }, { "Flame Breath", "Fire breath on everyone in front of him. Stay behind him." } }
T[227] = { { "Enrage", "Raises attack speed by 60% and damage for 2 minutes. Save your cooldowns and heal the tank." }, { "Whirlwind", "Spins for 2 seconds, hitting nearby players with heavy damage. Step away from him." }, { "Mortal Strike", "Heavy hit on the tank that cuts healing received by 50% for 5 seconds. Heal the tank carefully." }, { "Cleave", "Damages an enemy and its nearest allies, up to 3 targets. Keep the tank healed." } }
T[228] = { { "Terrifying Roar", "Sends all nearby players fleeing in fear for 5 seconds. Don't fight near other packs." }, { "Immolate", "Fire damage, then more every 3 seconds for 21 seconds. Dispel it." }, { "Fireball", "Fire damage to one player. Interrupt the cast." } }
T[229] = { { "Thunderclap", "Nature damage to nearby players, slows their movement by 40% and attack speed by 33% for 10 seconds. Heal the group." } }
